  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C04","C06","C07","C14","C15","C16","C17","C27","C31","C32","C37","C38","C41","C42","C44","C45","C46","C50","C52","C53","C55","C56","C57"],
  "claims": [
    {
      "claim": "The query is a 1,3-dimethylxanthine with an N7-dioxolanylmethyl substituent, sharing the xanthine core of theophylline and paraxanthine, for which human oral bioavailability is consistently high.",
      "card_ids": ["C04","C16"]
    },
    {
      "claim": "New L2 fed-state theophylline records show absolute or relative bioavailability of 83 to 114 percent across multiple sustained-release products, confirming high absorption when taken with food.",
      "card_ids": ["C31","C37","C41","C42","C46","C50","C52","C55","C56"]
    },
    {
      "claim": "Additional L2 fasted theophylline records show 98 to 103 percent for Uniphyllin and 98 percent for sustained-release tablets, while the lowest human values remain 53 to 77 percent.",
      "card_ids": ["C32","C38","C44","C45","C53","C57"]
    },
    {
      "claim": "The only sub-60 percent value is 47.8 percent in fasted beagle dogs, which is species-specific and still far above the 20 percent threshold.",
      "card_ids": ["C48"]
    },
    {
      "claim": "Non-xanthine L2 records for lamivudine, zalcitabine, emtricitabine, cladribine, and compound 12 do not transfer to this xanthine query and do not affect the decision.",
      "card_ids": ["C34","C35","C36","C39","C40","C43","C49","C54","C58"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C30","C31","C32","C33","C37","C38","C41","C42","C44","C45","C46","C47","C48","C50","C51","C52","C53","C55","C56","C57"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C34","C35","C36","C39","C40","C43","C49","C54","C58"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for doxofylline itself is supplied.",
    "The N7-dioxolanylmethyl substituent may alter absorption or first-pass metabolism relative to theophylline.",
    "Most supporting records are theophylline formulations with different release characteristics.",
    "The lowest human theophylline values come from specific sustained-release products and may not transfer exactly."
  ],
  "decision_summary": "High. The query is a 1,3-dimethylxanthine closely analogous to theophylline and paraxanthine. New L2 records add fed-state theophylline values of 83 to 114 percent and additional fasted values of 98 to 103 percent, confirming high human bioavailability across prandial states and formulations. The lowest human values of 53 to 77 percent and the dog value of 47.8 percent remain far above the 20 percent threshold. No close-analog record supports F below 20 percent, so the high prediction is strengthened."
}

